    # Detect Cross Col
    if cross_color is None:
        for c in range(W):
            color = grid[0][c]
            if color != bg_color and all(grid[r][c] == color for r in range(H)):
                cross_color = color
                cc = c
                break
    else:
        # If row found, look for the col of that color
        for c in range(W):
            if all(grid[r][c] == cross_color for r in range(H)):
                cc = c
                break

    out_H, out_W = H - 1, W - 1
    # Initialize output with BG
    output = [[bg_color] * out_W for _ in range(out_H)]

    if cross_color is None:
        # Fallback: copy BG
        return output

    for r in range(H):
        for c in range(W):
            val = grid[r][c]
            # Skip BG and Cross
            if val == bg_color: continue
            if val == cross_color: continue

            # Map input (r,c) to output (or_r, or_c)
