                or_c = c - 1

            # 4 reflections
            points = [
                (or_r, or_c),
                (out_H - 1 - or_r, or_c),
                (or_r, out_W - 1 - or_c),
                (out_H - 1 - or_r, out_W - 1 - or_c)
            ]

            for pr, pc in points:
                if 0 <= pr < out_H and 0 <= pc < out_W:
                    output[pr][pc] = cross_color

    return output
